def minimum_travel_time(n, h, a, b, k, queries):
    results = []

    for ta, fa, tb, fb in queries:
        if ta == tb:
            # Same tower, just need to move up or down floors
            time = abs(fa - fb)
        else:
            # Different towers
            if fa < a or fa > b:
                # If we are below the passage floor, we need to move up to a
                if fb < a:
                    # Both need to go up to a
                    time = abs(fa - a) + abs(tb - ta) + abs(fb - a)
                elif fb > b:
                    # Go up to a in tower a, cross, then go down to fb
                    time = abs(fa - a) + abs(tb - ta) + abs(fb - b)
                else:
                    # Go up to a, cross, then go down to fb
                    time = abs(fa - a) + abs(tb - ta) + abs(fb - a)
            elif fa >= a and fa <= b:
                if fb < a:
                    # Cross first and then go down
                    time = abs(fa - fb) + abs(tb - ta) + abs(fb - a)
                elif fb > b:
                    # Cross to fb above the range
                    time = abs(fa - fb) + abs(tb - ta) + abs(b - fb)
                else:
                    # If both are within passable range
                    time = abs(fa - fb) + abs(tb - ta)

        results.append(time)

    return results

