def min_operations(n, m, table):
    good_cells = []

    for i in range(n):
        for j in range(m):
            if table[i][j] == 1:
                good_cells.append((i + 1, j + 1))  # Store good cells in 1-based indexing

    corners = [(1, 1), (1, m), (n, 1), (n, m)]

    operations_needed = set()

    for good_x, good_y in good_cells:
        for corner_x, corner_y in corners:
            # Create a bounding box between the good cell and the corner cell
            x_min = min(good_x, corner_x)
            x_max = max(good_x, corner_x)
            y_min = min(good_y, corner_y)
            y_max = max(good_y, corner_y)

            # Collecting all affected cells
            for p in range(x_min, x_max + 1):
                for q in range(y_min, y_max + 1):
                    operations_needed.add((p, q))

    return len(operations_needed)

# Read input
