def lucky_number(s):
    lucky_digits = ['4', '7']
    count = {}

    for digit in s:
        if digit in lucky_digits:
            if digit not in count:
                count[digit] = 0
            count[digit] += 1

    if not count:
        return "-1"

    # Find the lucky number with the maximum frequency
    max_count = max(count.values())
    candidates = [digit for digit, freq in count.items() if freq == max_count]

